#include <stdio.h>
#include <stdlib.h>
typedef unsigned long u_long;

enum {
    ReplayWindowSize = 32
};

u_long bitmap = 0;                 /* セッションの状態 - 32ビットでなければならない */
u_long lastSeq = 0;                     /* セッションの状態 */

/* パケットが許可されなければ0、許可されれば1を返す */
int ChkReplayWindow(u_long seq);

int ChkReplayWindow(u_long seq) {
    u_long diff;

    if (seq == 0) return 0;             /* 最初が0、または一周した */
    if (seq > lastSeq) {                /* より大きい新しいシーケンス番号 */
        diff = seq - lastSeq;
        if (diff < ReplayWindowSize) {  /* ウィンドウ内 */
            bitmap <<= diff;
            bitmap |= 1;                /* このパケットのビットをセット */
        } else bitmap = 1;          /* このパケットは「ずっと大きい」 */
        lastSeq = seq;
        return 1;                       /* より大きいものは良い */
    }
    diff = lastSeq - seq;
    if (diff >= ReplayWindowSize) return 0; /* 古すぎる、または一周した */
    if (bitmap & ((u_long)1 << diff)) return 0; /* すでに見た */
    bitmap |= ((u_long)1 << diff);              /* 見たことを記録 */
    return 1;                           /* 順序は乱れているが良い */
}

char string_buffer[512];

#define STRING_BUFFER_SIZE sizeof(string_buffer)

int main() {
    int result;
    u_long last, current, bits;

    printf("Input initial state (bits in hex, last msgnum):\n");
    if (!fgets(string_buffer, STRING_BUFFER_SIZE, stdin)) exit(0);
    sscanf(string_buffer, "%lx %lu", &bits, &last);
    if (last != 0)
    bits |= 1;
    bitmap = bits;
    lastSeq = last;
    printf("bits:%08lx last:%lu\n", bitmap, lastSeq);
    printf("Input value to test (current):\n");

    while (1) {
        if (!fgets(string_buffer, STRING_BUFFER_SIZE, stdin)) break;
        sscanf(string_buffer, "%lu", &current);
        result = ChkReplayWindow(current);
        printf("%-3s", result ? "OK" : "BAD");
        printf(" bits:%08lx last:%lu\n", bitmap, lastSeq);
    }
    return 0;
}
